c.push(P('میکروسفرهای ژلاتینی از قدیمی‌ترین و در عین حال پرکاربردترین حامل‌های زیست‌تخریب‌پذیر برای رهایش موضعی و طولانی‌مدت دارو هستند؛ از آنتی‌بیوتیک در عفونت استخوان تا فاکتورهای رشد در مهندسی بافت. با وجود حجم قابل توجه مطالعات تجربی، طراحی این ذرات هنوز عمدتاً بر آزمون‌وخطا استوار است و مدل‌سازی ریاضی در این حوزه اغلب به برازش مدل‌های تجربی بر منحنی رهایش محدود مانده است. این گزارش با دو هدف نوشته شده است: نخست، مرور نظام‌مند و انتقادی مدل‌های ریاضی رهایش دارو، از روابط تجربی کلاسیک تا مدل‌های مکانیستی نفوذ، تورم، تخریب و اتصال و رویکردهای نوین یادگیری ماشین، مستقل از نوع پلیمر و دارو؛ و دوم، مرور تحلیلی 30 مقاله تجربی رهایش دارو از میکروسفرهای ژلاتینی، شامل 24 مقاله ممیزی‌شده در پایگاه داده پایان‌نامه، شش مقاله‌ای که منحنی رهایش آن‌ها به‌طور کامل استخراج شد و مقالات جدید سال 2026. برای هر مقاله، علاوه بر خلاصه، تحلیلی از اعتبار شواهد، سازوکار محتمل و ارزش آن برای مدل‌سازی ارائه شده است. در پایان، با کنار هم قرار دادن پیش‌بینی مدل نفوذ با ضریب نفوذ محاسبه‌شده از اصول اولیه و داده‌های تجربی، نشان داده می‌شود که رهایش از این ذرات 10^4 تا 10^7 برابر کندتر از حد نفوذی است و شواهد تجربی مستقل نیز به نقش غالب اتصال دارو به شبکه ژلاتین و تخریب آنزیمی اشاره دارند. بر این اساس، چارچوبی مرحله‌ای برای مدل‌سازی پیش‌بین رهایش از میکروسفرهای ژلاتینی پیشنهاد می‌شود.'));
c.push(P('واژگان کلیدی: میکروسفر ژلاتینی، مدل‌سازی رهایش دارو، نفوذ فیکی، تورم هیدروژل، تخریب آنزیمی، اتصال یونی، یادگیری ماشین', { size: 22, color: L.GREY, after: 200 }));

c.push(H1('1. مقدمه'));
c.push(H2('1-1. ژلاتین به‌عنوان حامل دارو'));
c.push(P('ژلاتین پروتئینی است که از هیدرولیز جزئی کلاژن پوست و استخوان به دست می‌آید. بسته به روش پیش‌فرآوری، دو نوع اصلی آن تولید می‌شود: ژلاتین نوع A که با فرآوری اسیدی به دست می‌آید و نقطه ایزوالکتریک آن در محدوده تقریبی 7 تا 9 است، و ژلاتین نوع B که با فرآوری قلیایی تولید می‌شود و نقطه ایزوالکتریک آن حدود 4.7 تا 5.4 است. این تفاوت پیامد مستقیمی برای رهایش دارد: در pH فیزیولوژیک، ژلاتین نوع B بار منفی خالص دارد و می‌تواند داروها و پروتئین‌های دارای بار مثبت را با برهم‌کنش الکترواستاتیک نگه دارد، در حالی که ژلاتین نوع A تقریباً خنثی یا کمی مثبت است. زیست‌سازگاری، زیست‌تخریب‌پذیری آنزیمی، قیمت پایین و سابقه طولانی مصرف دارویی، ژلاتین را به ماده‌ای جذاب برای سامانه‌های رهایش تبدیل کرده است.'));
c.push(P('ژلاتین در دمای بدن حل می‌شود؛ بنابراین برای ساخت ذره‌ای پایدار باید زنجیرهای آن به هم متصل شوند. رایج‌ترین عوامل اتصال عرضی عبارت‌اند از گلوتارآلدئید (واکنش با گروه‌های آمین لیزین، مؤثر ولی با نگرانی سمیت)، جنیپین (عامل طبیعی با سمیت بسیار کمتر)، کربودی‌ایمیدها (EDC/NHS که پیوند آمیدی مستقیم بین گروه‌های کربوکسیل و آمین ایجاد می‌کنند)، تانیک اسید و اتصال فیزیکی یا گرمایی. نوع و شدت اتصال عرضی همزمان سه ویژگی را تعیین می‌کند: میزان تورم، اندازه چشمه شبکه و سرعت تخریب؛ و همین سه، چنان‌که در ادامه نشان داده می‌شود، پارامترهای اصلی هر مدل رهایش‌اند.'));
